102	  context: CommandContext,
103	  args: string,
104	): Promise<void | MessageActionReturn> {
105	  const { config } = context.services;
106	  if (!config) {
107	    return {
108	      type: 'message',
109	      messageType: 'error',
110	      content: 'Config not loaded.',
111	    };
