28	export const HooksList: React.FC<HooksListProps> = ({ hooks }) => {
29	  if (hooks.length === 0) {
30	    return (
31	      <Box flexDirection="column" marginBottom={1}>
32	        <Text>No hooks configured.</Text>
33	      </Box>
34	    );
35	  }
36	
37	  // Group hooks by event name for better organization
38	  const hooksByEvent = hooks.reduce(
39	    (acc, hook) => {
40	      if (!acc[hook.eventName]) {
41	        acc[hook.eventName] = [];
