import type React from 'react';
import { useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry to be displayed in the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  enabled: boolean;
  matcher?: string;
  sequential?: boolean;
}

interface HooksDialogProps {
  hooks: HookEntry[];
  onClose: () => void;
  maxVisibleHooks?: number;
}

const DEFAULT_MAX_VISIBLE_HOOKS = 10;

/**
 * Get a display name for a hook, falling back to the command when no explicit
 * name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * Interactive dialog that displays the configured hooks grouped by event name.
 *
 * Unlike the previous approach of pushing a message into the UI feed, this
 * dialog is rendered separately from the message stream and can be dismissed
 * with the Escape key. When the number of hooks exceeds `maxVisibleHooks` the
 * list becomes scrollable using the up/down arrow keys.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks = DEFAULT_MAX_VISIBLE_HOOKS,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const maxScroll = Math.max(0, hooks.length - maxVisibleHooks);
  const isScrollable = hooks.length > maxVisibleHooks;

  useKeypress(
    (key) => {
      if (key.name === 'escape') {
        onClose();
        return true;
      }
      if (key.name === 'up') {
        setScrollOffset((prev) => Math.max(0, prev - 1));
        return true;
      }
      if (key.name === 'down') {
        setScrollOffset((prev) => Math.min(maxScroll, prev + 1));
        return true;
      }
      return false;
    },
    { isActive: true },
  );

  // Clamp the current offset in case the hook list shrank between renders.
  const clampedOffset = Math.min(scrollOffset, maxScroll);
  const visibleHooks = isScrollable
    ? hooks.slice(clampedOffset, clampedOffset + maxVisibleHooks)
    : hooks;

  const canScrollUp = isScrollable && clampedOffset > 0;
  const canScrollDown = isScrollable && clampedOffset < maxScroll;

  // Group the visible hooks by event name for better organization.
  const hooksByEvent = visibleHooks.reduce(
    (acc, hook) => {
      if (!acc[hook.eventName]) {
        acc[hook.eventName] = [];
      }
      acc[hook.eventName].push(hook);
      return acc;
    },
    {} as Record<string, HookEntry[]>,
  );

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.focused}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {hooks.length === 0 ? (
        <Box marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <Box flexDirection="column" paddingLeft={2} marginTop={1}>
          {canScrollUp && (
            <Text color={theme.text.secondary}>▲</Text>
          )}
          {Object.entries(hooksByEvent).map(([eventName, eventHooks]) => (
            <Box key={eventName} flexDirection="column" marginBottom={1}>
              <Text color={theme.text.accent} bold>
                {eventName}:
              </Text>
              <Box flexDirection="column" paddingLeft={2}>
                {eventHooks.map((hook, index) => {
                  const hookName = getHookDisplayName(hook);
                  const statusColor = hook.enabled
                    ? theme.status.success
                    : theme.text.secondary;
                  const statusText = hook.enabled ? 'enabled' : 'disabled';

                  return (
                    <Box
                      key={`${eventName}-${index}`}
                      flexDirection="column"
                    >
                      <Box>
                        <Text>
                          <Text color={theme.text.accent}>{hookName}</Text>
                          <Text color={statusColor}>
                            {` [${statusText}]`}
                          </Text>
                        </Text>
                      </Box>
                      <Box paddingLeft={2} flexDirection="column">
                        {hook.config.description && (
                          <Text italic>{hook.config.description}</Text>
                        )}
                        <Text dimColor>
                          Source: {hook.source}
                          {hook.config.name &&
                            hook.config.command &&
                            ` | Command: ${hook.config.command}`}
                          {hook.matcher && ` | Matcher: ${hook.matcher}`}
                          {hook.sequential && ` | Sequential`}
                          {hook.config.timeout &&
                            ` | Timeout: ${hook.config.timeout}s`}
                        </Text>
                      </Box>
                    </Box>
                  );
                })}
              </Box>
            </Box>
          ))}
          {canScrollDown && (
            <Text color={theme.text.secondary}>▼</Text>
          )}
        </Box>
      )}

      <Box marginTop={1} flexDirection="column">
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
        <Text color={theme.text.secondary}>
          {isScrollable ? '(Use ↑/↓ to scroll, Esc to close)' : '(Esc to close)'}
        </Text>
      </Box>
    </Box>
  );
};
